import { ciDetail, ciDel, cilistattr, savenameattr, ciuniqueSave, attrDelete } from "@/api/system/ciModel";
import { globalattrSearch } from "@/api/system/globalArrtManage";
import arrtForm from "./components/modelManageComponent/arrtForm";
import relForm from "./components/modelManageComponent/relForm";
import arrtEidtList from "./components/modelManageComponent/arrtEidtList";
import ciConfigForm from "./ciConfigForm";
import complianceCheck from "./components/modelManageComponent/complianceCheck";
import ciTypeList from "./components/modelManageComponent/ciTypeList";
export default {
  components: {
    arrtForm: arrtForm,
    relForm: relForm,
    arrtEidtList: arrtEidtList,
    complianceCheck: complianceCheck,
    ciTypeList: ciTypeList,
    ciConfigForm: ciConfigForm
  },
  props: ['ciId'],
  data: function data() {
    return {
      showRel: false,
      ciDetailData: {
        uniqueAttrIdList: []
      },
      showSider: true,
      activeName: 0,
      arrtList: [],
      checkList: [],
      globalArrtList: [],
      // 弹窗
      showArrtForm: false,
      showArrtList: false,
      showCiconfig: false,
      arrtId: '',
      showArrtType: '',
      showComplianceCheck: false
    };
  },
  mounted: function mounted() {
    var _this = this;
    setTimeout(function () {
      _this.setPageContentHeight('detail_top', 'detail_content');
    }, 500);
    this.getDetail(this.ciId);
  },
  methods: {
    getDetail: function getDetail(id) {
      var _this2 = this;
      this.pageLoading = true;
      ciDetail({
        id: id,
        needAction: true
      }).then(function (res) {
        _this2.ciDetailData = res.Return;
      });
      cilistattr({
        ciId: id
      }).then(function (res) {
        _this2.arrtList = res.Return;
      });
      globalattrSearch({
        isisActive: 1
      }).then(function (res) {
        _this2.globalArrtList = res.Return.tbodyList;
      });
    },
    // 侧边栏缩放
    siderControl: function siderControl() {
      this.showSider = !this.showSider;
    },
    // 查看继承模型
    seeParentCi: function seeParentCi(id) {
      this.getDetail(id);
    },
    // 修改名称属性
    changeRadio: function changeRadio(val) {
      var _this3 = this;
      var form = {
        ciId: this.ciId,
        attrId: val
      };
      savenameattr(form).then(function (res) {
        _this3.$message({
          type: 'success',
          message: '保存成功！'
        });
      });
    },
    // 修改唯一规则
    changeCheckbox: function changeCheckbox(val) {
      var _this4 = this;
      var form = {
        ciId: this.ciId,
        attrIdList: val
      };
      ciuniqueSave(form).then(function (res) {
        _this4.$message({
          type: 'success',
          message: '保存成功！'
        });
      });
    },
    // 删除模型
    delCi: function delCi() {
      var _this5 = this;
      this.$confirm('确定删除该模型?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        ciDel({
          id: _this5.ciId
        }).then(function (res) {
          _this5.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this5.$emit('delci');
        });
      });
    },
    // 编辑属性
    editArrt: function editArrt(row) {
      this.showArrtForm = true;
      this.showArrtType = '修改';
      this.arrtId = row.id;
    },
    // 删除属性
    delArrt: function delArrt(row) {
      var _this6 = this;
      // return
      this.$confirm("\u786E\u5B9A\u5220\u9664\u5C5E\u6027\uFF1A".concat(row.label, "\uFF1F"), '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        attrDelete({
          id: row.id
        }).then(function (res) {
          _this6.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this6.getDetail(_this6.ciId);
        });
      });
    },
    // 保存属性回调
    saveArrt: function saveArrt() {
      this.showArrtForm = false;
      this.getDetail(this.ciId);
    },
    // 保存关系
    saveRel: function saveRel() {
      this.showRel = false;
      this.getDetail(this.ciId);
    },
    // 保存显示设置回调
    saveView: function saveView() {
      this.showArrtList = false;
      this.getDetail(this.ciId);
    },
    saveCompliance: function saveCompliance() {
      this.showComplianceCheck = false;
      this.getDetail(this.ciId);
    },
    // 更多配置
    commandDrop: function commandDrop(val) {
      if (val === 'view') {
        this.showArrtList = true;
      } else if (val === 'check') {
        this.showComplianceCheck = true;
      } else if (val == 'export') {
        var params = {
          ciId: this.ciId
        };
        this.download("/api/idevelop-cmdb/cmdb/ci/export", params, "导出模型.model");
      }
    },
    // 查看配置项
    seeConfig: function seeConfig() {
      this.$refs.ciConfig.style.width = '100%';
      this.showCiconfig = true;
    },
    // 配置返回详情
    backDetail: function backDetail() {
      this.$refs.ciConfig.style.width = '0';
      this.showCiconfig = false;
    },
    // 点击左侧树
    clickCiTree: function clickCiTree(val) {
      this.getDetail(val.id);
      this.$emit("update:ciId", this.ciId = val.id);
    }
  }
};
